import{_ as n,o as i,c as t,ah as r}from"./chunks/framework.Bja9t6Wf.js";const c=JSON.parse('{"title":"Drehbuch-Update: Szene 22 - Die Emoji-Lektion","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/szene-emoji-lektion.md","filePath":"logbuch/szene-emoji-lektion.md"}'),s={name:"logbuch/szene-emoji-lektion.md"};function a(o,e,h,u,d,l){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="drehbuch-update-szene-22-die-emoji-lektion" tabindex="-1">Drehbuch-Update: Szene 22 - Die Emoji-Lektion <a class="header-anchor" href="#drehbuch-update-szene-22-die-emoji-lektion" aria-label="Permalink to &quot;Drehbuch-Update: Szene 22 - Die Emoji-Lektion&quot;">​</a></h1><p><em>Stil:</em> Eine traumartige Sequenz, in der sich die Zeiten vermischen. Schwarz-Weiß-Ästhetik trifft auf moderne Smartphone-Beleuchtung.</p><p><em>Besetzung:</em></p><ul><li>Helmut Horten: August Diehl</li><li>Der junge Sekretär (Schmid-Typ): Ein nervöser Schauspieler in einem viel zu engen Slim-Fit-Anzug.</li></ul><hr><p><strong>INT. HORTENS ARBEITSZIMMER - NACHT</strong></p><p>Horten (Diehl) sitzt am Schreibtisch. Er hält einen Federhalter in der Hand. Vor ihm steht der junge Sekretär, der hektisch auf seinem Smartphone tippt.</p><p><strong>HORTEN</strong> (ohne aufzusehen): Woran arbeiten Sie da, mein Junge?</p><p><strong>SEKRETÄR</strong> (begeistert): Ich schicke gerade eine Bestätigung für den Vorstandsposten der Staats-Holding raus, Herr Horten! Mit zwei Raketen-Emojis und einem Bizeps. Die Leute sollen wissen, dass wir Gas geben!</p><p>Horten legt den Federhalter langsam ab. Das Geräusch schneidet durch den Raum.</p><p><strong>HORTEN</strong>: Raketen? Bizeps? Sie hinterlassen Fußabdrücke in einem Sumpf, aus dem Sie nie wieder herauskommen werden.</p><p><strong>SEKRETÄR</strong>: Aber es ist verschlüsselt! Wir sind die Familie!</p><p><strong>HORTEN</strong> (steht langsam auf, tritt ins Licht): Hören Sie mir gut zu. Ein Deal ist wie ein guter Wein: Er braucht Dunkelheit, Stille und... kein Protokoll. Wenn Sie ein Versprechen geben, geben Sie es mit einem Händedruck. Wenn Sie Macht ausüben, tun Sie es mit einem Blick. Aber niemals, hören Sie, niemals mit einem gelben, lachenden Gesichtchen in einer Cloud.</p><p>Er tritt ganz nah an den Sekretär heran. Seine Stimme ist eiskalt.</p><p><strong>HORTEN</strong>: In fünfzig Jahren wird man meine Konten suchen und nichts finden außer Legenden. Man wird Ihre Telefon-Clouds suchen und nichts finden außer... Peinlichkeiten.</p><p><strong>FADE TO BLACK.</strong></p>',16)])])}const p=n(s,[["render",a]]);export{c as __pageData,p as default};
